def medicare_amount(year: str, state: str, code: str, facility: bool = False) -> int | None:
    """Cents Medicare allows a physician for one unit in that year and state; None when the code is not priced here."""
    v = MPFS.get(year, {}).get(state, {}).get(code)
    return (v[1] if facility else v[0]) if v else None
